# Copy the sans_inopinatus category gene fnas from 0_busco_sc_genes_merged_fnas/ into 1_filtered_busco_sc_genes/
# This is the most inclusive category and has everything we need (other 2 categories are subsets of this)
mkdir ../1_filtered_busco_sc_genes
for gene in "${sans_inopinatus_genes[@]}"; do
	cp "../0_busco_sc_genes_merged_fnas/${gene}.fna" ../1_filtered_busco_sc_genes;
	done

echo "Put the ~900 genes subset in 1_filtered_busco_sc_genes/!"


### Here we are subsetting AFTER alignment
# This is the next most inclusive one (we're permissive with the non-Ixodes ones having missing data)
mkdir ../2b_aligned_all_ixodes_genes
for gene in "${all_ixodes_represented_genes[@]}"; do
	cp "../2_aligned_filtered_busco_sc_genes/${gene}_mafft_align.fna" ../2b_aligned_all_ixodes_genes;
	done

echo "Put the aligned ~230 genes subset in 2b_aligned_all_ixodes_genes/!"

